const OTHER_MARKET: MarketCatalogEntry = {
  numericId: 99,
  code: "OTHER",
  slug: "other",
  category: MarketCategory.INNE,
    subCategory: "inne",
  labels: { pl: "Inne", en: "Other" },
  descriptions: { pl: "Nierozpoznany typ rynku", en: "Unknown market type" },
  hasParameter: false,
  selections: [],
  // audit-match (Arsenal vs Coventry City) UX gap-analysis: OTHER is a
  // catch-all bucket that can carry dozens of genuinely unrelated raw
  // bookmaker markets (a single bookmaker offered up to 134 selections here
  // for one match). BINARY_BUTTONS is designed for real 2-outcome markets
  // and its renderer intentionally caps display at 2 selections — applied
  // to OTHER, that silently dropped the other 132 selections with no
  // indication anything was missing. COMBINATION has no such cap and
  // renders every selection type present, which is the correct behavior for
  // an unbounded catch-all (the underlying "different unrelated products
  // sharing one generic label" problem is a normalizer-routing issue, not
  // fixable purely by choice of viewType — see report section 21).
  viewType: ViewType.COMBINATION,
  displayOrder: 999,
};

export const MARKET_CATALOG: MarketCatalogEntry[] = [
  ...MAIN_MARKETS,
  ...GOALS_MARKETS,
  ...HANDICAP_MARKETS,
  ...HALF_TIME_MARKETS,
  ...CORRECT_SCORE_MARKETS,
  ...PLAYER_MARKETS,
  ...STATISTICS_MARKETS,
  ...COMBINATION_MARKETS,
  ...ADDITIONAL_MARKETS,
  ...WAVE_EXPANSION_MARKETS,
  ...MATCH_AUDIT_WAVE_MARKETS,
  OTHER_MARKET,
];

export const CATALOG_BY_CODE = new Map<string, MarketCatalogEntry>(
  MARKET_CATALOG.map((m) => [m.code, m])
);

export const CATALOG_BY_NUMERIC_ID = new Map<number, MarketCatalogEntry>(
  MARKET_CATALOG.map((m) => [m.numericId, m])
);

export const CATALOG_BY_SLUG = new Map<string, MarketCatalogEntry>(
  MARKET_CATALOG.map((m) => [m.slug, m])
);

export const CANONICAL_CODES = new Set<string>(MARKET_CATALOG.map((m) => m.code));

export function getMarketMetadata(code: string): MarketCatalogEntry | undefined {
  return CATALOG_BY_CODE.get(code);
}

export function isValidMarketCode(code: string): boolean {
  return CANONICAL_CODES.has(code);
}

export function getCategoryForMarket(code: string): MarketCategory {
  return CATALOG_BY_CODE.get(code)?.category ?? MarketCategory.INNE;
}

export function hasParameters(code: string): boolean {
  return CATALOG_BY_CODE.get(code)?.hasParameter ?? false;
}

